<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';import { message } from 'ant-design-vue';import { CheckCircleOutlined, ClockCircleOutlined, CloseCircleOutlined, RightOutlined } from '@ant-design/icons-vue';import UserPageLayout from '../components/UserPageLayout.vue';import { api,type ApiResponse } from '../services/api'
type Order={id:number;orderId:string;orderStatus:string|null;orderTime:string|null;shopName:string|null;productName:string|null;purchaseValue:number|null;actualCommission:number|null;userCommission:number|null;subId:string|null}
const rows=ref<Order[]>([]),loading=ref(false),tab=ref('Pending'),page=ref(1),total=ref(0),selected=ref<Order|null>(null);const limit=15
const fetchData=async()=>{loading.value=true;try{const r=await api.get<ApiResponse<{orders:Order[];total:number}>>('/api/user/orders',{params:{page:page.value,limit,status:tab.value}});rows.value=r.data.data?.orders||[];total.value=r.data.data?.total||0}catch{message.error('Không thể tải đơn hàng.')}finally{loading.value=false}}
onMounted(fetchData);watch(tab,()=>{page.value=1;fetchData()});const money=(v:number|null)=>new Intl.NumberFormat('vi-VN').format(v||0)+'đ';const label=(s:string|null)=>s==='Completed'?'Hoàn thành':s==='Cancelled'?'Đã hủy':s==='Unpaid'?'Chờ thanh toán':'Chờ duyệt'
</script>
<template><UserPageLayout><div class="space-y-6"><div><h1 class="text-2xl font-black text-slate-900">Tra cứu <span class="text-[#ee4d2d]">đơn hàng</span></h1><p class="mt-1 text-sm text-slate-500">Theo dõi tiến trình ghi nhận và hoàn tiền đơn Shopee của bạn.</p></div><a-alert v-if="tab==='Pending'" type="warning" show-icon message="Đơn đang chờ Shopee xác nhận hoàn tất thời gian hủy, đổi trả." class="!rounded-xl"/><a-card :bordered="false" class="!rounded-2xl"><a-tabs v-model:activeKey="tab"><a-tab-pane key="Pending"><template #tab><ClockCircleOutlined/> Chờ duyệt</template></a-tab-pane><a-tab-pane key="Completed"><template #tab><CheckCircleOutlined/> Thành công</template></a-tab-pane><a-tab-pane key="Cancelled"><template #tab><CloseCircleOutlined/> Đã hủy</template></a-tab-pane></a-tabs><a-spin :spinning="loading"><div v-if="rows.length" class="divide-y divide-slate-100"><button v-for="item in rows" :key="item.id" class="flex w-full items-center gap-4 py-4 text-left hover:bg-orange-50/40" @click="selected=item"><div class="h-10 w-10 shrink-0 rounded-full border border-orange-100 bg-orange-50 p-2"><img src="/logo/shopee.png" class="h-full w-full object-contain"/></div><div class="min-w-0 flex-1"><div class="truncate text-sm font-bold text-slate-800">{{item.productName||'Sản phẩm Shopee'}}</div><div class="mt-1 text-[11px] text-slate-400">#{{item.orderId}} · {{item.orderTime?new Date(item.orderTime).toLocaleString('vi-VN'):'—'}}</div></div><div class="text-right"><div class="text-sm font-black text-emerald-600">+{{money(item.userCommission)}}</div><span class="mt-1 inline-block rounded-full px-2 py-0.5 text-[9px] font-bold" :class="item.orderStatus==='Completed'?'bg-emerald-50 text-emerald-600':item.orderStatus==='Cancelled'?'bg-rose-50 text-rose-600':'bg-amber-50 text-amber-600'">{{label(item.orderStatus)}}</span></div><RightOutlined class="text-slate-300"/></button></div><a-empty v-else-if="!loading" description="Không có đơn hàng ở trạng thái này"/></a-spin><div v-if="total>limit" class="mt-5 flex justify-center"><a-pagination :current="page" :total="total" :page-size="limit" @change="(p:number)=>{page=p;fetchData()}"/></div></a-card><a-drawer :open="!!selected" title="Chi tiết đơn hàng" width="430" @close="selected=null"><div v-if="selected" class="space-y-4"><div v-for="x in [{l:'Mã đơn',v:selected.orderId},{l:'Sản phẩm',v:selected.productName||'Sản phẩm Shopee'},{l:'Cửa hàng',v:selected.shopName||'Shopee'},{l:'Giá trị đơn',v:money(selected.purchaseValue)},{l:'Tiền hoàn',v:money(selected.userCommission)},{l:'Trạng thái',v:label(selected.orderStatus)}]" :key="x.l" class="rounded-xl border border-slate-200 p-4"><div class="text-[10px] font-bold uppercase text-slate-400">{{x.l}}</div><div class="mt-1 text-sm font-bold text-slate-800">{{x.v}}</div></div></div></a-drawer></div></UserPageLayout></template>
